<script setup>
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { getAdminRestaurant, updateAdminRestaurantStatus } from '../../services/admin'
import { useToastStore } from '../../stores/toast'
import BaseAlert from '../../components/ui/BaseAlert.vue'
import BaseBadge from '../../components/ui/BaseBadge.vue'
import BaseButton from '../../components/ui/BaseButton.vue'
import BaseCard from '../../components/ui/BaseCard.vue'
import BaseConfirmDialog from '../../components/ui/BaseConfirmDialog.vue'
import BaseLoading from '../../components/ui/BaseLoading.vue'

const route = useRoute(); const { t } = useI18n(); const toast = useToastStore(); const loading = ref(true); const saving = ref(false); const error = ref(''); const restaurant = ref(null); const confirming = ref(false)
async function load() { try { restaurant.value = await getAdminRestaurant(route.params.id) } catch { error.value = 'admin.loadError' } finally { loading.value = false } }
async function changeStatus() { saving.value = true; try { const status = restaurant.value.platform_status === 'active' ? 'suspended' : 'active'; restaurant.value = await updateAdminRestaurantStatus(restaurant.value.id, status); toast.success(t(status === 'active' ? 'admin.restaurantReactivated' : 'admin.restaurantSuspended')); confirming.value = false } catch { toast.error(t('admin.updateError')) } finally { saving.value = false } }
onMounted(load)
</script>

<template><section class="admin-page"><RouterLink class="admin-back" :to="{ name: 'admin-restaurants' }">← {{ $t('admin.backToRestaurants') }}</RouterLink><BaseAlert v-if="error" type="error">{{ $t(error) }}</BaseAlert><BaseLoading v-if="loading" :rows="5" /><template v-else-if="restaurant"><header class="page-heading"><div><h1>{{ restaurant.name_ar || restaurant.name_en || restaurant.name }}</h1><p>{{ restaurant.slug }}</p></div><BaseBadge :variant="restaurant.platform_status === 'active' ? 'success' : 'danger'">{{ $t(`admin.${restaurant.platform_status}`) }}</BaseBadge></header><div class="admin-metrics"><BaseCard><span>{{ $t('admin.categories') }}</span><strong>{{ restaurant.categories_count }}</strong></BaseCard><BaseCard><span>{{ $t('admin.menuItems') }}</span><strong>{{ restaurant.menu_items_count }}</strong></BaseCard><BaseCard><span>{{ $t('admin.views') }}</span><strong>{{ restaurant.public_menu_views }}</strong></BaseCard><BaseCard><span>{{ $t('admin.qrVisits') }}</span><strong>{{ restaurant.qr_visits }}</strong></BaseCard><BaseCard><span>{{ $t('admin.whatsappClicks') }}</span><strong>{{ restaurant.whatsapp_clicks }}</strong></BaseCard><BaseCard><span>{{ $t('admin.phoneClicks') }}</span><strong>{{ restaurant.phone_clicks }}</strong></BaseCard></div><div class="admin-detail-grid"><BaseCard><h2>{{ $t('admin.restaurantDetails') }}</h2><dl class="admin-details"><div><dt>{{ $t('admin.arabicName') }}</dt><dd>{{ restaurant.name_ar || '—' }}</dd></div><div><dt>{{ $t('admin.englishName') }}</dt><dd>{{ restaurant.name_en || '—' }}</dd></div><div><dt>{{ $t('admin.owner') }}</dt><dd><RouterLink :to="{ name: 'admin-user-detail', params: { id: restaurant.owner.id } }">{{ restaurant.owner.name }} · {{ restaurant.owner.email }}</RouterLink></dd></div><div><dt>{{ $t('admin.ownerVisibility') }}</dt><dd>{{ $t(restaurant.is_active ? 'admin.ownerPublished' : 'admin.ownerUnpublished') }}</dd></div><div><dt>{{ $t('admin.language') }}</dt><dd>{{ restaurant.default_language }}</dd></div><div><dt>{{ $t('admin.currency') }}</dt><dd>{{ restaurant.currency }}</dd></div><div><dt>{{ $t('admin.theme') }}</dt><dd>{{ restaurant.theme_key }}</dd></div><div><dt>{{ $t('admin.created') }}</dt><dd>{{ new Date(restaurant.created_at).toLocaleString() }}</dd></div><div><dt>{{ $t('admin.updated') }}</dt><dd>{{ new Date(restaurant.updated_at).toLocaleString() }}</dd></div></dl><BaseButton :variant="restaurant.platform_status === 'active' ? 'danger' : 'primary'" @click="confirming = true">{{ $t(restaurant.platform_status === 'active' ? 'admin.suspend' : 'admin.reactivate') }}</BaseButton></BaseCard><BaseCard><h2>{{ $t('admin.brandImages') }}</h2><div class="admin-brand-images"><figure><figcaption>{{ $t('admin.logo') }}</figcaption><img v-if="restaurant.logo_url" :src="restaurant.logo_url" :alt="$t('admin.logo')"><span v-else>—</span></figure><figure><figcaption>{{ $t('admin.cover') }}</figcaption><img v-if="restaurant.cover_image_url" :src="restaurant.cover_image_url" :alt="$t('admin.cover')"><span v-else>—</span></figure></div><h2>{{ $t('admin.publicMenu') }}</h2><a class="ui-button ui-button-ghost" :href="`/menu/${restaurant.slug}`" target="_blank" rel="noopener">{{ $t('admin.openPublicMenu') }}</a></BaseCard></div><BaseConfirmDialog :open="confirming" :loading="saving" danger :message="$t(restaurant.platform_status === 'active' ? 'admin.suspendRestaurantConfirm' : 'admin.reactivateRestaurantConfirm')" @confirm="changeStatus" @cancel="confirming = false" /></template></section></template>
